import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-09-19 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-09-19 :: Ceph Performance Meeting","date":"2019-09-19T00:00:00.000Z","updated":"2019-10-01T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","BlueStore","RGW","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-19_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-09-19_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-09-19_-_-_Ceph_Performance_Meeting.md"};function s(p,e,n,a,_,g){return o(),r("div",null,[...e[0]||(e[0]=[l("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Rob（公司技术团队）、Luke（公司技术团队）、会议主持人（Ceph研发人员）</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph社区动态</strong></p><ul><li>讨论了本周Ceph社区的更新，包括3个新的Pull Request，涉及BlueStore错误修复、OSD截止值调整、OST操作诊断简化等。</li><li>审查了RGW、Loose Store、Teaches的更新，以及Sam的ODMG跟踪点PR。</li><li>MDS缓存内存限制和Sharding工作仍在进行中，但遇到了RocksDB损坏问题。</li></ul><p><strong>二、公司集群性能问题</strong></p><ul><li>公司集群配置：120个节点，每个节点一个OSD，使用RAID 5 24盘驱动器，总容量约3.5PB，运行版本14.2.4。</li><li>性能问题：在进行大数据分析时，Rgw读取和写入性能下降，出现段错误和超时。</li><li>集群中其他服务（如Elasticsearch和S3）性能未受影响。</li></ul><p><strong>三、讨论和建议</strong></p><ul><li>建议检查OSD内存目标设置，考虑从默认4GB增加到16GB或32GB。</li><li>建议检查Rgw内存使用情况，确保未超出限制。</li><li>建议检查Rgw配置，确保未启用导致性能下降的选项。</li><li>建议尝试使用更小的RAID配置，例如RAID 1或RAID 10。</li><li>建议在Rgw容器中启用调试功能，以便收集更多错误信息。</li></ul><p><strong>四、后续行动计划</strong></p><ul><li>Rob和Luke将根据讨论的建议对集群进行配置更改，并观察性能是否有所改善。</li><li>Rob和Luke将记录所有更改和观察结果，并在下次会议中分享。</li></ul><p><strong>五、其他</strong></p><ul><li>讨论了Ceph的元数据存储、RocksDB性能优化、NVMe存储和对象存储等话题。</li><li>Seagate公司代表Philip和Mark介绍了他们的工作，包括自主存储设备和嵌入存储等。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了公司Ceph集群的性能问题，并提出了相应的解决方案。参会人员将根据讨论结果进行配置更改，并观察性能是否有所改善。</p>",16)])])}const d=t(i,[["render",s]]);export{u as __pageData,d as default};
